begin;
select no_plan();
create function pg_temp.tid(n int) returns uuid language sql immutable as $$select ('a7230000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.tid(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','transfer'||n||'@test.invalid' from generate_series(901,903) n;
insert into public.profiles(id,role,name) select pg_temp.tid(n),case n when 901 then 'admin' when 902 then 'teacher' else 'staff' end,'transfer actor'||n from generate_series(901,903) n on conflict(id) do update set role=excluded.role;
delete from public.teacher_catalogs where profile_id=pg_temp.tid(902);
insert into public.teacher_catalogs(id,name,subjects,profile_id) values(pg_temp.tid(101),'transfer teacher',array['영어'],pg_temp.tid(902));
update public.profiles set teacher_catalog_id=pg_temp.tid(101) where id=pg_temp.tid(902);
insert into public.classroom_catalogs(id,name,subjects) values(pg_temp.tid(201),'transfer room',array['영어']);
select set_config('request.jwt.claim.sub',pg_temp.tid(901)::text,true);
create function pg_temp.seed(n int, amount int default 4) returns uuid language plpgsql as $$
declare pid uuid:=pg_temp.tid(n); begin
 insert into public.timetable_plans(id,name,created_by) values(pid,'fixture-transfer-plan-'||n,pg_temp.tid(901));
 for j in 1..amount loop
 insert into public.timetable_plan_items(id,plan_id,name,subject,grade,capacity,tuition) values(pg_temp.tid(n*100+j),pid,'fixture-transfer-'||n||'-'||j,'영어','중2',12,100000);
 insert into public.timetable_plan_slots(id,plan_id,item_id,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name)
 values(pg_temp.tid(n*100+j+50),pid,pg_temp.tid(n*100+j),0,60*j,60*j+30,pg_temp.tid(101),pg_temp.tid(201),'transfer teacher','transfer room');
 end loop;return pid; end $$;
create function pg_temp.req(n int, target int, mode text default 'copy', amount int default 1, conflict text default 'reject') returns jsonb language sql as $$
select jsonb_build_object('source',jsonb_build_object('kind','plan','planId',pg_temp.tid(n)),'target',case when target=0 then jsonb_build_object('kind','operational') else jsonb_build_object('kind','plan','planId',pg_temp.tid(target)) end,'mode',mode,'onConflict',conflict,'itemIds',(select jsonb_agg(pg_temp.tid(n*100+j)) from generate_series(1,amount) j)) $$;
create function pg_temp.command(r jsonb,k text) returns jsonb language sql as $$select jsonb_build_object('request',r,'previewFingerprint',public.preview_timetable_plan_transfer_v1(r)->>'fingerprint','requestKey',k)$$;
create temp table saved(k text primary key, command jsonb, response jsonb);
grant all on saved to authenticated;
select has_function('public','preview_timetable_plan_transfer_v1',array['jsonb'],'transfer preview exists');
select has_function('public','commit_timetable_plan_transfer_v1',array['jsonb'],'atomic transfer exists');
select ok(not has_function_privilege('anon','public.commit_timetable_plan_transfer_v1(jsonb)','execute'),'anon denied');
select ok(not has_function_privilege('authenticated','dashboard_private.evaluate_timetable_transfer_v1(jsonb)','execute'),'private evaluator denied');
select pg_temp.seed(1);select pg_temp.seed(2,0);
set local role authenticated;
select throws_ok($$select public.preview_timetable_plan_transfer_v1(pg_temp.req(1,1))$$,'22023','timetable_invalid','same plan denied');
select throws_ok($$select public.preview_timetable_plan_transfer_v1(pg_temp.req(1,0)||jsonb_build_object('itemIds',jsonb_build_array(pg_temp.tid(101),pg_temp.tid(101))))$$,'22023','timetable_invalid','duplicate selection denied');
select throws_ok($$select public.preview_timetable_plan_transfer_v1(pg_temp.req(1,0,'copy',1,'keep_pending'))$$,'22023','timetable_invalid','operating keep_pending denied');
select throws_ok($$select public.preview_timetable_plan_transfer_v1(pg_temp.req(1,2,'move',1,'keep_pending'))$$,'22023','timetable_invalid','move keep_pending denied');
select throws_ok($$select public.preview_timetable_plan_transfer_v1(pg_temp.req(1,0)||'{"noConflict":true}')$$,'22023','timetable_invalid','client conflict bypass denied');
reset role;
-- Repeated matrix uses savepoints: every direction/mode/count starts identical.
savepoint matrix;
set local role authenticated;
insert into saved select '0-copy-1',pg_temp.command(pg_temp.req(1,0,'copy',1),'0-copy-1'),null;
update saved set response=public.commit_timetable_plan_transfer_v1(command) where k='0-copy-1';
select is(jsonb_array_length((select response->'mappings' from saved where k='0-copy-1')),1,'0-copy-1 all selected mappings');
select is(public.commit_timetable_plan_transfer_v1((select command from saved where k='0-copy-1')),(select response from saved where k='0-copy-1'),'0-copy-1 immutable replay');
select is((select count(*)::int from public.timetable_plan_items where plan_id=pg_temp.tid(1)),4,'0-copy-1 source count');
select is(jsonb_array_length(public.get_timetable_plan_v1(pg_temp.tid(1))->'slots'),3,'0-copy-1 canonical source excludes applied');
select is((select count(*)::int from public.classes where name like 'fixture-transfer-%' and status='수강'),1,'0-copy-1 new active classes');
select ok(not exists(select 1 from public.classes where name like 'fixture-transfer-%' and (student_ids<>'[]'::jsonb or waitlist_ids<>'[]'::jsonb or textbook_ids<>'[]'::jsonb or textbook_usage<>'{}'::jsonb or lessons<>'[]'::jsonb)),'0-copy-1 no roster textbook history copied');
select is((select count(*)::int from public.class_lesson_sessions s join public.classes c on c.id=s.class_id where c.name like 'fixture-transfer-%'),0,'0-copy-1 no sessions generated');
reset role;
rollback to matrix;
